@startuml

class Patient {
  + PatientID : int
  + Name : string
  + Symptoms : string[]
}

abstract class Doctor {
  + DoctorID : int
  + Name : string
  + Specialization : string
}

class HeadDoctor {}

class Diagnosis {
  + DiagnosisID : int
  + Description : string
  + PriorityScore : string
}

class TreatmentPlan {
  + PlanID : int
  + Description : string
}

abstract class Treatment {
  + TreatmentID : int
  + Stage : int
  + ConsentRequired : boolean
}

class Stage1Treatment {}

class Stage2Treatment {}

class Stage3Treatment {}

class PatientDiagnosis {
  + ID : int
  + Patient : Patient
  + Diagnosis : Diagnosis
}

class DoctorDiagnosis {
  + ID : int
  + Doctor : Doctor
  + Diagnosis : Diagnosis
}

class TreatmentApplication {
  + ID : int
  + PatientDiagnosis : PatientDiagnosis
  + Treatment : Treatment
}

class ConsentForm {
  + FormID : int
  + Patient : Patient
  + DateSigned : datetime
}

Patient "1" -- "*" PatientDiagnosis
HeadDoctor "1" -- "*" DoctorDiagnosis
DoctorDiagnosis "1" -- "*" Diagnosis
Diagnosis "1" -- "*" TreatmentPlan
TreatmentPlan "1" -- "*" Treatment
Stage1Treatment --|> Treatment
Stage2Treatment --|> Treatment
Stage3Treatment --|> Treatment
PatientDiagnosis "1" -- "*" TreatmentApplication
ConsentForm "0..*" -- "1" TreatmentApplication

@enduml

